import { ankitProfile, portfolioProjects } from "./knowledge";

export interface RetrievedDocument {
  id: string;
  type: "profile" | "experience" | "project" | "education";
  title: string;
  content: string;
}

function normalize(text: string) {
  return text
    .toLowerCase()
    .replace(/[^\w\s.-]/g, " ")
    .replace(/\s+/g, " ")
    .trim();
}

function tokenize(text: string) {
  return normalize(text)
    .split(" ")
    .filter((word) => word.length > 2);
}

function scoreDocument(query: string, document: RetrievedDocument) {
  const queryWords = tokenize(query);
  const documentText = normalize(
    `${document.title} ${document.content}`,
  );

  let score = 0;

  for (const word of queryWords) {
    if (documentText.includes(word)) {
      score += 1;
    }
  }

  // Stronger matching for exact phrases
  if (documentText.includes(normalize(query))) {
    score += 5;
  }

  return score;
}

function buildDocuments(): RetrievedDocument[] {
  const documents: RetrievedDocument[] = [];

  documents.push({
    id: "profile",
    type: "profile",
    title: "Ankit Rathore Profile",
    content: JSON.stringify(ankitProfile),
  });

  for (const experience of ankitProfile.experience) {
    documents.push({
      id: `experience-${experience.company}`,
      type: "experience",
      title: `${experience.role} at ${experience.company}`,
      content: JSON.stringify(experience),
    });
  }

  for (const education of ankitProfile.education) {
    documents.push({
      id: `education-${education.institution}`,
      type: "education",
      title: education.institution,
      content: JSON.stringify(education),
    });
  }

  for (const project of portfolioProjects) {
    documents.push({
      id: `project-${project.slug}`,
      type: "project",
      title: project.title,
      content: JSON.stringify(project),
    });
  }

  return documents;
}

const documents = buildDocuments();

export function retrieveRelevantDocuments(
  query: string,
  limit = 5,
): RetrievedDocument[] {
  return documents
    .map((document) => ({
      document,
      score: scoreDocument(query, document),
    }))
    .filter((item) => item.score > 0)
    .sort((a, b) => b.score - a.score)
    .slice(0, limit)
    .map((item) => item.document);
}